const accounts = $input.first().json.accounts ?? [];
return accounts
  .filter((a) => ['shopee', 'lazada', 'tiktok'].includes(a.platform) && a.sync_enabled)
  .map((a) => ({ json: {
    business_id: a.business_id, account_id: a.id, platform: a.platform, label: a.label,
    // Overlap the window on purpose. Every order is upserted on the
    // marketplace's own id, so seeing one twice costs nothing and missing one
    // costs a sale.
    since: Math.floor((Date.now() - 15 * 60 * 1000) / 1000),
    until: Math.floor(Date.now() / 1000),
  } }));

// Shopee: order/get_order_list with the detail fields asked for in one go,
// including escrow, so the money comes back with the order rather than needing
// a second signed call per order.
const crypto = require('crypto');
const creds = $('Shop Credentials').item.json.credentials;
const item = $('One Shop Each').item.json;
const host = creds.host || 'https://partner.shopeemobile.com';
const path = '/api/v2/order/get_order_list';
const ts = Math.floor(Date.now() / 1000);
const base = `${creds.partner_id}${path}${ts}${creds.access_token}${creds.shop_id}`;
const sign = crypto.createHmac('sha256', creds.partner_key).update(base).digest('hex');
const query = new URLSearchParams({
  partner_id: String(creds.partner_id), timestamp: String(ts),
  access_token: creds.access_token, shop_id: String(creds.shop_id), sign,
  time_range_field: 'update_time', time_from: String(item.since), time_to: String(item.until),
  page_size: '50', response_optional_fields: 'order_status,total_amount,buyer_username,item_list,payment_method',
});
return [{ json: { ...item, url: `${host}${path}?${query}`, vendor: 'shopee' } }];

// Lazada: /orders/get over the same window. Items come back on a second call
// per order in Lazada's API; the normaliser below asks for them only when an
// order is new to us, which keeps the call count sane.
const crypto = require('crypto');
const creds = $('Shop Credentials').item.json.credentials;
const item = $('One Shop Each').item.json;
const host = creds.host || 'https://api.lazada.com.ph/rest';
const path = '/orders/get';
const params = {
  app_key: creds.app_key, access_token: creds.access_token,
  timestamp: String(Date.now()), sign_method: 'sha256',
  update_after: new Date(item.since * 1000).toISOString(),
  limit: '50', sort_direction: 'DESC',
};
const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
const sign = crypto.createHmac('sha256', creds.app_secret)
  .update(path + sorted).digest('hex').toUpperCase();
return [{ json: { ...item, url: `${host}${path}?${new URLSearchParams({ ...params, sign })}`,
                  vendor: 'lazada' } }];

// TikTok Shop: order/202309/orders/search. A POST, so the body is part of the
// signature too.
const crypto = require('crypto');
const creds = $('Shop Credentials').item.json.credentials;
const item = $('One Shop Each').item.json;
const host = creds.host || 'https://open-api.tiktokglobalshop.com';
const path = '/order/202309/orders/search';
const body = JSON.stringify({ update_time_ge: item.since, update_time_lt: item.until });
const params = { app_key: creds.app_key, shop_cipher: creds.shop_cipher,
                 timestamp: String(Math.floor(Date.now() / 1000)),
                 version: '202309', page_size: '50' };
const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
const base = creds.app_secret + path + sorted + body + creds.app_secret;
const sign = crypto.createHmac('sha256', creds.app_secret).update(base).digest('hex');
return [{ json: { ...item, url: `${host}${path}?${new URLSearchParams({ ...params, sign })}`,
                  method: 'POST', payload: JSON.parse(body),
                  access_token: creds.access_token, vendor: 'tiktok' } }];

const item = $('One Shop Each').item.json;
return [{ json: { ...item, skipped: true,
  error: `No order reader is wired up for ${item.platform} yet.` } }];

// One shape for all three. The important part is what counts as paid, and the
// three disagree about the words while agreeing about the substance:
//
//   Shopee   UNPAID -> READY_TO_SHIP -> SHIPPED -> COMPLETED
//   Lazada   unpaid -> pending -> ready_to_ship -> shipped -> delivered
//   TikTok   UNPAID -> AWAITING_SHIPMENT -> IN_TRANSIT -> DELIVERED
//
// Cash on delivery is a payment method, not a status: a COD order is shipped
// while it is still unpaid, and only becomes money when the courier hands it
// over. That is why the method is carried through rather than guessed from
// the status.
const item = $('One Shop Each').item.json;
const body = $input.item.json;
const out = [];

const STATUS = {
  UNPAID: 'UNPAID', TO_CONFIRM_RECEIVE: 'SHIPPED', READY_TO_SHIP: 'READY_TO_SHIP',
  PROCESSED: 'READY_TO_SHIP', SHIPPED: 'SHIPPED', COMPLETED: 'DELIVERED',
  CANCELLED: 'CANCELLED', INVOICE_PENDING: 'PAID',
  unpaid: 'UNPAID', pending: 'PAID', packed: 'READY_TO_SHIP', ready_to_ship: 'READY_TO_SHIP',
  shipped: 'SHIPPED', delivered: 'DELIVERED', canceled: 'CANCELLED', returned: 'RETURNED',
  AWAITING_SHIPMENT: 'PAID', AWAITING_COLLECTION: 'READY_TO_SHIP',
  IN_TRANSIT: 'SHIPPED', DELIVERED: 'DELIVERED', COMPLETE: 'DELIVERED',
};
const method = (raw) => {
  const text = String(raw ?? '').toLowerCase();
  if (!text) return 'unknown';
  if (text.includes('cod') || text.includes('cash on delivery')) return 'cod';
  if (text.includes('wallet') || text.includes('gcash') || text.includes('paymaya')) return 'wallet';
  if (text.includes('bank') || text.includes('transfer')) return 'bank_transfer';
  if (text.includes('instal')) return 'installment';
  return 'online';
};
// Which of this shop's streams, if any, is on air. TikTok Shop's order API
// does not hand back the room an order was bought in, so the thing that is
// actually knowable is used instead: the shop is live, and the order was
// placed after the stream started. That is what a seller means by a live sale,
// and the backend will not guess any further than this — two rooms open on one
// shop and the order stays a shopfront order rather than going to the wrong
// stream.
const rooms = ($('Open Rooms').first().json.sessions ?? [])
  .filter((s) => s.account_id === item.account_id);
const roomFor = (placedAt) => {
  if (rooms.length !== 1) return null;
  const room = rooms[0];
  if (!room.started_at) return null;
  const placed = placedAt ? Date.parse(placedAt) : Date.now();
  return Number.isFinite(placed) && placed >= Date.parse(room.started_at) ? room : null;
};

const push = (o) => {
  const room = roomFor(o.placed_at);
  out.push({ json: {
    business_id: item.business_id, account_id: item.account_id,
    source: room ? 'live' : 'shop',
    ...(room ? { live_session_id: room.id, live_room_id: room.external_id ?? null } : {}),
    ...o,
  } });
};

if (item.platform === 'shopee') {
  for (const o of body?.response?.order_list ?? []) {
    push({
      external_id: String(o.order_sn), order_no: String(o.order_sn),
      buyer_name: o.buyer_username ?? 'Buyer',
      status: STATUS[o.order_status] ?? 'UNPAID',
      total: Number(o.total_amount ?? 0), currency: o.currency ?? 'PHP',
      placed_at: o.create_time ? new Date(o.create_time * 1000).toISOString() : null,
      payment: { method: method(o.payment_method),
                 state: STATUS[o.order_status] === 'UNPAID' ? 'AWAITING' : 'IN_ESCROW' },
      items: (o.item_list ?? []).map((i) => ({
        sku: i.model_sku || i.item_sku, name: i.item_name,
        qty: Number(i.model_quantity_purchased ?? 1),
        unit_price: Number(i.model_discounted_price ?? i.model_original_price ?? 0) })),
    });
  }
} else if (item.platform === 'lazada') {
  for (const o of body?.data?.orders ?? []) {
    const raw = Array.isArray(o.statuses) ? o.statuses[0] : o.statuses;
    push({
      external_id: String(o.order_id), order_no: String(o.order_number ?? o.order_id),
      buyer_name: [o.customer_first_name, o.customer_last_name].filter(Boolean).join(' ') || 'Buyer',
      status: STATUS[raw] ?? 'UNPAID',
      total: Number(o.price ?? 0), currency: 'PHP',
      placed_at: o.created_at ?? null,
      payment: { method: method(o.payment_method),
                 state: STATUS[raw] === 'UNPAID' ? 'AWAITING' : 'IN_ESCROW' },
      // Lazada returns lines on /order/items/get; until that call is made the
      // order is recorded without them rather than with invented ones.
      items: [],
    });
  }
} else if (item.platform === 'tiktok') {
  for (const o of body?.data?.orders ?? []) {
    push({
      external_id: String(o.id), order_no: String(o.id),
      buyer_name: o.recipient_address?.name ?? 'Buyer',
      status: STATUS[o.status] ?? 'UNPAID',
      total: Number(o.payment?.total_amount ?? 0),
      currency: o.payment?.currency ?? 'PHP',
      placed_at: o.create_time ? new Date(o.create_time * 1000).toISOString() : null,
      payment: {
        method: o.payment_method_name ? method(o.payment_method_name) : 'online',
        state: STATUS[o.status] === 'UNPAID' ? 'AWAITING' : 'IN_ESCROW',
        gross: Number(o.payment?.sub_total ?? 0),
        shipping_fee: Number(o.payment?.shipping_fee ?? 0),
      },
      items: (o.line_items ?? []).map((i) => ({
        sku: i.seller_sku, name: i.product_name, qty: 1,
        unit_price: Number(i.sale_price ?? 0) })),
    });
  }
}
return out;

const accounts = $input.first().json.accounts ?? [];
const day = 24 * 60 * 60 * 1000;
return accounts
  .filter((a) => ['shopee', 'lazada', 'tiktok'].includes(a.platform) && a.sync_enabled)
  .map((a) => ({ json: {
    business_id: a.business_id, account_id: a.id, platform: a.platform,
    from: new Date(Date.now() - 7 * day).toISOString().slice(0, 10),
    to: new Date().toISOString().slice(0, 10),
  } }));

// Shopee: payment/get_payout_detail. Escrow is released per order and then
// paid out in a batch; this reads the batch and the orders inside it.
const crypto = require('crypto');
const creds = $('Payout Credentials').item.json.credentials;
const item = $('One Payout Each').item.json;
const host = creds.host || 'https://partner.shopeemobile.com';
const path = '/api/v2/payment/get_payout_detail';
const ts = Math.floor(Date.now() / 1000);
const base = `${creds.partner_id}${path}${ts}${creds.access_token}${creds.shop_id}`;
const sign = crypto.createHmac('sha256', creds.partner_key).update(base).digest('hex');
const query = new URLSearchParams({
  partner_id: String(creds.partner_id), timestamp: String(ts),
  access_token: creds.access_token, shop_id: String(creds.shop_id), sign,
  payout_time_from: String(Math.floor(new Date(item.from).getTime() / 1000)),
  payout_time_to: String(Math.floor(new Date(item.to).getTime() / 1000) + 86399),
  page_size: '20' });
return [{ json: { ...item, url: `${host}${path}?${query}`, vendor: 'shopee' } }];

// Lazada: /finance/payout/status/get, which returns the statement periods and
// what was transferred for each.
const crypto = require('crypto');
const creds = $('Payout Credentials').item.json.credentials;
const item = $('One Payout Each').item.json;
const host = creds.host || 'https://api.lazada.com.ph/rest';
const path = '/finance/payout/status/get';
const params = { app_key: creds.app_key, access_token: creds.access_token,
                 timestamp: String(Date.now()), sign_method: 'sha256',
                 created_after: item.from };
const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
const sign = crypto.createHmac('sha256', creds.app_secret)
  .update(path + sorted).digest('hex').toUpperCase();
return [{ json: { ...item, url: `${host}${path}?${new URLSearchParams({ ...params, sign })}`,
                  vendor: 'lazada' } }];

// TikTok Shop: finance/202309/statements, then the payments inside each.
const crypto = require('crypto');
const creds = $('Payout Credentials').item.json.credentials;
const item = $('One Payout Each').item.json;
const host = creds.host || 'https://open-api.tiktokglobalshop.com';
const path = '/finance/202309/statements';
const params = { app_key: creds.app_key, shop_cipher: creds.shop_cipher,
                 timestamp: String(Math.floor(Date.now() / 1000)), version: '202309',
                 statement_time_ge: String(Math.floor(new Date(item.from).getTime() / 1000)),
                 page_size: '20' };
const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
const base = creds.app_secret + path + sorted + creds.app_secret;
const sign = crypto.createHmac('sha256', creds.app_secret).update(base).digest('hex');
return [{ json: { ...item, url: `${host}${path}?${new URLSearchParams({ ...params, sign })}`,
                  access_token: creds.access_token, vendor: 'tiktok' } }];

const item = $('One Payout Each').item.json;
return [{ json: { ...item, skipped: true,
  error: `No payout reader is wired up for ${item.platform} yet.` } }];

// What came in, and which orders the platform says are in it. The backend adds
// up what those orders say they are worth and reports the difference; nothing
// here tries to make the two agree.
const item = $('One Payout Each').item.json;
const body = $input.item.json;
const out = [];
const push = (p) => out.push({ json: { business_id: item.business_id,
  account_id: item.account_id, currency: 'PHP', ...p } });

if (item.platform === 'shopee') {
  for (const p of body?.response?.payout_list ?? []) {
    push({
      external_id: String(p.payout_id ?? p.payout_time),
      net: Number(p.payout_amount ?? 0),
      gross: Number(p.total_amount ?? p.payout_amount ?? 0),
      fees: Number(p.total_fee ?? 0),
      settled_at: p.payout_time ? new Date(p.payout_time * 1000).toISOString() : null,
      orders: (p.order_list ?? []).map((o) => ({
        external_id: String(o.order_sn), amount: Number(o.escrow_amount ?? 0) })),
    });
  }
} else if (item.platform === 'lazada') {
  for (const p of body?.data ?? []) {
    push({
      external_id: String(p.statement_number ?? p.id),
      net: Number(p.payout ?? 0), gross: Number(p.item_revenue ?? 0),
      fees: Number(p.fees ?? 0), adjustments: Number(p.refunds ?? 0),
      period_start: p.open_date ?? null, period_end: p.close_date ?? null,
      settled_at: p.paid_date ?? null,
      // Lazada's statement does not carry its order lines; without them the
      // backend records the payout and says plainly that none matched, which
      // is the truth rather than a clean-looking zero.
      orders: [],
    });
  }
} else if (item.platform === 'tiktok') {
  for (const p of body?.data?.statements ?? []) {
    push({
      external_id: String(p.id),
      net: Number(p.settlement_amount ?? 0),
      gross: Number(p.revenue_amount ?? 0),
      fees: Number(p.fee_amount ?? 0),
      adjustments: Number(p.adjustment_amount ?? 0),
      settled_at: p.statement_time
        ? new Date(p.statement_time * 1000).toISOString() : null,
      orders: [],
    });
  }
}
return out;

// Only the ones inside the chasing window. An order past the cancel mark is
// not nudged again — it is left for the owner to cancel, because cancelling
// somebody's order is not a thing a bot should do on a timer.
const body = $input.item.json;
return (body.chase ?? []).map((o) => ({ json: { order_id: o.id, order_no: o.order_no,
  buyer: o.buyer_name, minutes_old: Math.round(Number(o.minutes_old)) } }));
